// GENERATED by scripts/embed-admin.mjs — edit admin/*.html instead.
export const ADMIN_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Pass Studio — Admin</title>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/qrcode-generator/1.4.4/qrcode.min.js\"></script>\n<style>\n  :root{\n    --bg:#f6f6f4; --panel:#fff; --ink:#1a1a1a; --ink-soft:#6b6b6b; --line:#e7e5e0;\n    --crimson:#a4133c; --crimson-deep:#800f2f; --blush:#fff0f3; --good:#1a7f4e; --chip:#f1efe9;\n    --card-bg:linear-gradient(160deg,#800f2f 0%,#a4133c 55%,#c9184a 100%);\n  }\n  *{box-sizing:border-box;margin:0;padding:0;}\n  body{font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Inter,Roboto,sans-serif;background:var(--bg);color:var(--ink);min-height:100vh;}\n\n  .topbar{display:flex;align-items:center;gap:14px;padding:12px 22px;background:var(--panel);border-bottom:1px solid var(--line);}\n  .brandmark{display:flex;align-items:center;gap:9px;font-weight:700;font-size:15px;}\n  .brandmark .dot{width:26px;height:26px;border-radius:8px;background:var(--card-bg);display:grid;place-items:center;color:#fff;font-size:13px;}\n  .crumb{color:var(--ink-soft);font-size:13px;}\n  .topbar .right{margin-left:auto;display:flex;gap:10px;align-items:center;}\n  .btn{border:1px solid var(--line);background:#fff;padding:8px 14px;border-radius:9px;font-size:13px;font-weight:600;cursor:pointer;font-family:inherit;color:var(--ink);transition:all .13s;}\n  .btn:hover{border-color:#cfcbc2;}\n  .btn.primary{background:var(--crimson);border-color:var(--crimson);color:#fff;}\n  .btn.primary:hover{background:var(--crimson-deep);}\n  .btn.ghost{border-color:transparent;color:var(--ink-soft);}\n  .btn:disabled{opacity:.5;cursor:default;}\n\n  .wrap{max-width:980px;margin:0 auto;padding:26px 22px 60px;}\n\n  /* key gate */\n  .gate{max-width:420px;margin:80px auto;background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:28px;text-align:center;}\n  .gate .dot{width:44px;height:44px;border-radius:13px;background:var(--card-bg);display:grid;place-items:center;color:#fff;font-size:21px;margin:0 auto 14px;}\n  .gate h1{font-size:18px;margin-bottom:6px;}\n  .gate p{font-size:13px;color:var(--ink-soft);margin-bottom:18px;line-height:1.5;}\n  .gate input{width:100%;border:1px solid var(--line);border-radius:10px;padding:11px 13px;font-size:14px;font-family:inherit;margin-bottom:12px;text-align:center;}\n  .gate .err{color:var(--crimson);font-size:12.5px;margin-top:10px;display:none;}\n\n  /* list */\n  .head-row{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;}\n  .head-row h1{font-size:19px;}\n  .head-row .sub{font-size:13px;color:var(--ink-soft);margin-top:3px;}\n  .list{background:var(--panel);border:1px solid var(--line);border-radius:14px;overflow:hidden;}\n  .row{display:flex;align-items:center;gap:14px;padding:14px 18px;border-bottom:1px solid var(--line);}\n  .row:last-child{border-bottom:0;}\n  .row .name{font-size:14px;font-weight:700;}\n  .row .name .ev{font-weight:500;color:var(--ink-soft);font-size:13px;}\n  .row .serial{font-family:ui-monospace,Menlo,monospace;font-size:11.5px;}\n  .row.archived{opacity:.55;background:#fbfaf7;}\n  .pill.sched{background:#fff4e0;color:#8a5a00;}\n  .logbox{border-bottom:1px solid var(--line);background:#fbfaf7;padding:10px 18px 12px 30px;}\n  .logline{font-size:12.5px;padding:4px 0;line-height:1.5;}\n  .logline.pending{color:#8a5a00;}\n  .logline .soft,.logline.soft{color:var(--ink-soft);}\n  .arch-tag{font-size:9.5px;font-weight:800;letter-spacing:.8px;color:var(--ink-soft);background:var(--chip);padding:2px 7px;border-radius:99px;vertical-align:middle;}\n  .row .meta{font-size:12px;color:var(--ink-soft);margin-top:3px;}\n  .row .grow{flex:1;min-width:0;}\n  .pill{display:inline-flex;align-items:center;gap:6px;font-size:11.5px;font-weight:700;padding:4px 10px;border-radius:99px;}\n  .pill.live{background:#e8f5ee;color:var(--good);}\n  .pill.live::before{content:\"\";width:7px;height:7px;border-radius:50%;background:var(--good);}\n  .pill.idle{background:var(--chip);color:var(--ink-soft);}\n  .row .actions{display:flex;gap:8px;}\n  .empty{padding:46px;text-align:center;color:var(--ink-soft);font-size:14px;line-height:1.6;}\n\n  /* modal */\n  .overlay{position:fixed;inset:0;background:rgba(20,10,14,.45);display:none;align-items:center;justify-content:center;z-index:50;padding:20px;}\n  .overlay.show{display:flex;}\n  .modal{background:#fff;border-radius:16px;max-width:440px;width:100%;padding:22px;box-shadow:0 24px 70px -20px rgba(0,0,0,.4);}\n  .modal h2{font-size:16px;margin-bottom:4px;}\n  .modal .sub{font-size:12.5px;color:var(--ink-soft);margin-bottom:16px;font-family:ui-monospace,Menlo,monospace;}\n  .modal label{display:block;font-size:11px;font-weight:700;letter-spacing:.6px;color:var(--ink-soft);margin:12px 0 5px;}\n  .modal input,.modal textarea{width:100%;border:1px solid var(--line);border-radius:9px;padding:10px 12px;font-size:13.5px;font-family:inherit;resize:vertical;}\n  .modal textarea{min-height:74px;}\n  .modal .foot{display:flex;justify-content:flex-end;gap:10px;margin-top:18px;}\n  .modal .note{font-size:12px;color:var(--ink-soft);margin-top:12px;line-height:1.5;}\n  .fields-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px;}\n  #qrBox{display:grid;place-items:center;padding:10px 0 4px;}\n  #qrBox img{border:1px solid var(--line);border-radius:12px;padding:10px;background:#fff;}\n\n  .toast{position:fixed;bottom:26px;left:50%;transform:translateX(-50%) translateY(8px);background:var(--ink);color:#fff;font-size:13px;padding:10px 18px;border-radius:99px;opacity:0;transition:all .25s;pointer-events:none;z-index:99;}\n  .toast.show{opacity:1;transform:translateX(-50%) translateY(0);}\n  .demo-badge{background:#ffd166;color:#5c4400;font-size:11px;font-weight:800;padding:3px 10px;border-radius:99px;letter-spacing:.5px;}\n</style>\n</head>\n<body>\n\n<div class=\"topbar\">\n  <div class=\"brandmark\"><div class=\"dot\">♥</div> Pass Studio</div>\n  <div class=\"crumb\">All About Love · Kindness Card</div>\n  <span class=\"demo-badge\" id=\"demoBadge\" style=\"display:none\">DEMO DATA</span>\n  <div class=\"right\">\n    <button class=\"btn\" id=\"builderBtn\" style=\"display:none\" onclick=\"location.href='/admin/builder'\">🎨 Builder</button>\n    <button class=\"btn\" id=\"brandsBtn\" style=\"display:none\" onclick=\"showBrands()\">🏷 Brands</button>\n    <button class=\"btn\" id=\"newCardBtn\" style=\"display:none\">＋ New test card</button>\n    <button class=\"btn ghost\" id=\"lockBtn\" style=\"display:none\">Sign out</button>\n  </div>\n</div>\n\n<!-- key gate -->\n<div class=\"gate\" id=\"gate\">\n  <div class=\"dot\">♥</div>\n  <h1>Pass Studio Admin</h1>\n  <p>Enter your admin key to manage cards.<br>It stays on this device.</p>\n  <input type=\"password\" id=\"keyInput\" placeholder=\"Admin key\" onkeydown=\"if(event.key==='Enter')connect()\">\n  <button class=\"btn primary\" style=\"width:100%\" onclick=\"connect()\">Connect</button>\n  <div class=\"err\" id=\"gateErr\">That key was rejected — check it and try again.</div>\n</div>\n\n<!-- main -->\n<div class=\"wrap\" id=\"main\" style=\"display:none\">\n  <div class=\"head-row\">\n    <div>\n      <h1>Cards</h1>\n      <div class=\"sub\" id=\"countSub\">—</div>\n    </div>\n    <button class=\"btn\" onclick=\"loadPasses()\">↻ Refresh</button>\n  </div>\n  <div class=\"list\" id=\"list\"><div class=\"empty\">Loading…</div></div>\n</div>\n\n<!-- notify modal -->\n<div class=\"overlay\" id=\"notifyOverlay\">\n  <div class=\"modal\">\n    <h2>Send a notification</h2>\n    <div class=\"sub\" id=\"notifySerial\"></div>\n    <label>MESSAGE (APPEARS ON THE LOCK SCREEN)</label>\n    <textarea id=\"notifyMsg\" placeholder=\"Your act of kindness ends tomorrow.\"></textarea>\n    <div class=\"note\">Delivered to every iPhone this card is installed on. Apple mutes cards that are updated too frequently — in production, keep to the reminder schedule.</div>\n    <div class=\"foot\">\n      <button class=\"btn\" onclick=\"hide('notifyOverlay')\">Cancel</button>\n      <button class=\"btn primary\" id=\"notifySend\" onclick=\"sendNotify()\">➤ Send</button>\n    </div>\n  </div>\n</div>\n\n<!-- edit modal -->\n<div class=\"overlay\" id=\"editOverlay\">\n  <div class=\"modal\">\n    <h2>Edit card fields</h2>\n    <div class=\"sub\" id=\"editSerial\"></div>\n    <div class=\"fields-grid\">\n      <div><label>GUEST</label><input id=\"f_guest\"></div>\n      <div><label>EVENT</label><input id=\"f_event\"></div>\n      <div><label>DUE</label><input id=\"f_due\"></div>\n      <div><label>ACTS DONE</label><input id=\"f_acts\"></div>\n    </div>\n    <label>PROMISE (FRONT OF CARD)</label><input id=\"f_promise\">\n    <label>THE MOVEMENT</label><input id=\"f_movement\">\n    <label>PHOTO URL (guest photo — square on Apple, wide hero on Google)</label><input id=\"f_photoUrl\" placeholder=\"https://…/photo.jpg\">\n    <div class=\"note\">Saving pushes the changes silently to installed cards (no notification unless you also send a message).</div>\n    <div class=\"foot\">\n      <button class=\"btn\" onclick=\"hide('editOverlay')\">Cancel</button>\n      <button class=\"btn primary\" onclick=\"saveFields()\">Save & push</button>\n    </div>\n  </div>\n</div>\n\n<!-- brands modal -->\n<div class=\"overlay\" id=\"brandsOverlay\">\n  <div class=\"modal\">\n    <h2>Brands</h2>\n    <div class=\"sub\">Each brand gets its own API key for creating cards</div>\n    <div id=\"brandsList\" style=\"margin-bottom:14px\"></div>\n    <label>NEW BRAND — ID (short, lowercase)</label><input id=\"b_id\" placeholder=\"binah\">\n    <label>NAME (shown on cards)</label><input id=\"b_name\" placeholder=\"Binah\">\n    <div id=\"brandKeyBox\" style=\"display:none;margin-top:12px;background:var(--blush);border:1px solid var(--crimson);border-radius:10px;padding:12px\">\n      <div style=\"font-size:11px;font-weight:800;letter-spacing:.6px;color:var(--crimson)\">API KEY — SHOWN ONLY ONCE, COPY IT NOW</div>\n      <div id=\"brandKeyVal\" style=\"font-family:ui-monospace,Menlo,monospace;font-size:12px;word-break:break-all;margin:8px 0\"></div>\n      <button class=\"btn\" onclick=\"copyBrandKey()\">Copy key</button>\n    </div>\n    <div class=\"foot\">\n      <button class=\"btn\" onclick=\"hide('brandsOverlay')\">Close</button>\n      <button class=\"btn primary\" onclick=\"createBrand()\">Create brand</button>\n    </div>\n  </div>\n</div>\n\n<!-- apple re-add modal -->\n<div class=\"overlay\" id=\"appleOverlay\">\n  <div class=\"modal\">\n    <h2>Add to Apple Wallet</h2>\n    <div class=\"sub\" id=\"appleSerial\"></div>\n    <div id=\"appleBody\"><div class=\"note\" style=\"text-align:center\">Preparing the link…</div></div>\n    <div class=\"note\">This is the SAME card (same serial) — scan with the iPhone camera, or open the link in Safari on the iPhone. Works for second devices and replacements; updates keep flowing to every device that adds it.</div>\n    <div class=\"foot\">\n      <button class=\"btn\" id=\"appleCopy\" style=\"display:none\" onclick=\"copyAppleLink()\">Copy link</button>\n      <button class=\"btn\" onclick=\"hide('appleOverlay')\">Done</button>\n    </div>\n  </div>\n</div>\n\n<!-- google save-link modal -->\n<div class=\"overlay\" id=\"googleOverlay\">\n  <div class=\"modal\">\n    <h2>Save to Google Wallet</h2>\n    <div class=\"sub\" id=\"googleSerial\"></div>\n    <div id=\"googleBody\"><div class=\"note\" style=\"text-align:center\">Creating the Google pass…</div></div>\n    <div class=\"note\">Demo mode: only accounts listed in your Google Wallet console (admins & test users) can save this card until publishing access is granted. Scan with an Android phone, or open the link in a browser signed into your Google account.</div>\n    <div class=\"foot\">\n      <button class=\"btn\" id=\"googleCopy\" style=\"display:none\" onclick=\"copyGoogleLink()\">Copy link</button>\n      <button class=\"btn\" onclick=\"hide('googleOverlay')\">Done</button>\n    </div>\n  </div>\n</div>\n\n<!-- new card modal -->\n<div class=\"overlay\" id=\"qrOverlay\">\n  <div class=\"modal\">\n    <h2>Add a test card to an iPhone</h2>\n    <div class=\"sub\">Scan with the iPhone camera → opens in Safari → Add</div>\n    <div id=\"qrBox\"></div>\n    <div class=\"note\" id=\"qrUrlNote\" style=\"text-align:center\"></div>\n    <div class=\"foot\">\n      <button class=\"btn\" onclick=\"hide('qrOverlay')\">Done</button>\n    </div>\n  </div>\n</div>\n\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\nconst APPLE_SVG = '<svg width=\"13\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"currentColor\" style=\"vertical-align:-2px\"><path d=\"M12.152 6.896c-.948 0-2.415-1.078-3.96-1.04-2.04.027-3.91 1.183-4.961 3.014-2.117 3.675-.546 9.103 1.519 12.09 1.013 1.454 2.208 3.09 3.792 3.031 1.52-.065 2.09-.987 3.935-.987 1.831 0 2.35.987 3.96.948 1.637-.026 2.676-1.48 3.676-2.948 1.156-1.688 1.636-3.325 1.662-3.415-.039-.013-3.182-1.221-3.22-4.857-.026-3.04 2.48-4.494 2.597-4.559-1.429-2.09-3.623-2.324-4.39-2.376-2-.156-3.675 1.09-4.61 1.09zM15.53 3.83c.843-1.012 1.4-2.427 1.245-3.83-1.207.052-2.662.805-3.532 1.818-.78.896-1.454 2.338-1.273 3.714 1.338.104 2.715-.688 3.559-1.702z\"/></svg>';\nconst DEMO = new URLSearchParams(location.search).has('demo');\nconst BASE = DEMO ? '' : location.origin;\nlet KEY = null, currentSerial = null;\n\n/* ── demo data ── */\nconst demoPasses = [\n  { serial: 'b6efd3a4-0af3-45aa-9041-4b6e079afd27', guest: 'Sarah', event: 'Rivera Wedding', created_at: Date.now()/1000-3600, updated_at: Date.now()/1000-120, registrations: 1 },\n  { serial: '8fb5edf0-b3a3-465c-bbea-9df620e998e2', guest: 'Marcus', event: 'Rivera Wedding', created_at: Date.now()/1000-7200, updated_at: Date.now()/1000-3800, registrations: 0 },\n  { serial: '713c1514-120a-49af-b54f-926cc06938e2', guest: null, event: null, created_at: Date.now()/1000-90000, updated_at: Date.now()/1000-90000, registrations: 0 },\n];\nconst demoFields = { guest:'Sarah', event:'Rivera Wedding', due:'Aug 11', acts:'0', promise:'I promised an act of kindness', movement:'Act #247,801 of one million' };\n\nasync function api(path, opts = {}) {\n  if (DEMO) return demoApi(path, opts);\n  const res = await fetch(BASE + path, {\n    ...opts,\n    headers: { 'X-Admin-Key': KEY, 'Content-Type': 'application/json', ...(opts.headers||{}) },\n  });\n  if (res.status === 401) throw new Error('unauthorized');\n  return res.json();\n}\nasync function demoApi(path, opts) {\n  await new Promise(r=>setTimeout(r,250));\n  if (path === '/v1/passes' && !opts.method) return { passes: demoPasses };\n  if (path.includes('/google-link')) return { saveUrl: 'https://pay.google.com/gp/v/save/DEMO.JWT.LINK' };\n  if (path.includes('/apple-link')) return { url: 'https://demo.example/v1/passes/demo/apple.pkpass?t=demo' };\n  if (path === '/v1/brands' && opts.method === 'POST') return { ok:true, apiKey: 'demo_' + 'x'.repeat(40) };\n  if (path === '/v1/brands') return { brands: [ { id:'love', name:'All About Love', created_at: Date.now()/1000-86400 } ] };\n  if (path.includes('/log')) return { events: [\n    { at: Date.now()/1000-120, kind: 'notified', message: 'You did it — act #251,442 💗', apple: 'pushed:1', google: 'updated+notified' },\n    { at: Date.now()/1000-3600, kind: 'updated', message: null, apple: 'pushed:1', google: 'updated' },\n    { at: Date.now()/1000-7200, kind: 'created', message: 'via API by brand love (+3 scheduled)', apple: null, google: null },\n  ], scheduled: [ { send_at: Date.now()/1000+86400, message: 'Your act of kindness ends tomorrow.', sent_at: null } ] };\n  if (opts.method === 'POST' && path.includes('action=archive')) { demoPasses.find(p=>path.includes(p.serial)).archived_at = Date.now()/1000; return { ok:true }; }\n  if (opts.method === 'POST' && path.includes('action=unarchive')) { demoPasses.find(p=>path.includes(p.serial)).archived_at = null; return { ok:true }; }\n  if (opts.method === 'PATCH') return { ok:true, pushed:1, results:[{device:'demo',status:200}] };\n  if (path.startsWith('/v1/passes/')) return { fields: demoFields };\n  return {};\n}\n\n/* ── auth flow ── */\nasync function connect() {\n  KEY = document.getElementById('keyInput').value.trim();\n  if (!KEY && !DEMO) return;\n  try {\n    await api('/v1/passes');\n    localStorage.setItem('psk', KEY || 'demo');\n    enter();\n  } catch { document.getElementById('gateErr').style.display = 'block'; }\n}\nfunction enter() {\n  document.getElementById('gate').style.display = 'none';\n  document.getElementById('main').style.display = 'block';\n  document.getElementById('newCardBtn').style.display = '';\n  document.getElementById('brandsBtn').style.display = '';\n  document.getElementById('builderBtn').style.display = '';\n  document.getElementById('lockBtn').style.display = '';\n  loadPasses();\n}\ndocument.getElementById('lockBtn').onclick = () => { localStorage.removeItem('psk'); location.reload(); };\ndocument.getElementById('newCardBtn').onclick = showQr;\n\n/* ── list ── */\nfunction rel(ts) {\n  const s = Math.max(1, Math.floor(Date.now()/1000 - ts));\n  if (s < 90) return s + 's ago';\n  if (s < 5400) return Math.round(s/60) + 'm ago';\n  if (s < 129600) return Math.round(s/3600) + 'h ago';\n  return Math.round(s/86400) + 'd ago';\n}\nlet showArchived = false;\nfunction passRow(p) {\n  const archived = !!p.archived_at;\n  return `\n      <div class=\"row${archived ? ' archived' : ''}\">\n        <div class=\"grow\">\n          <div class=\"name\">${esc(p.guest) || 'Unnamed card'}${p.event ? ' <span class=\"ev\">· ' + esc(p.event) + '</span>' : ''}${archived ? ' <span class=\"arch-tag\">ARCHIVED</span>' : ''}</div>\n          <div class=\"meta\"><span class=\"serial\">${p.serial.slice(0,8)}…</span> · created ${rel(p.created_at)} · updated ${rel(p.updated_at)}</div>\n        </div>\n        ${p.pending_msgs>0 ? '<span class=\"pill sched\">🕐 '+p.pending_msgs+' queued</span>' : ''}\n        ${p.registrations>0\n          ? '<span class=\"pill live\">'+p.registrations+' device'+(p.registrations===1?'':'s')+'</span>'\n          : '<span class=\"pill idle\">not added yet</span>'}\n        <div class=\"actions\">${archived\n          ? `<button class=\"btn\" onclick=\"unarchivePass('${p.serial}')\">↩︎ Unarchive</button>`\n          : `<button class=\"btn\" ${p.registrations?'':'disabled'} onclick=\"showNotify('${p.serial}')\">🔔 Notify</button>\n             <button class=\"btn\" onclick=\"showEdit('${p.serial}')\">✎ Edit</button>\n             <button class=\"btn\" onclick=\"showAppleLink('${p.serial}')\" title=\"Add to Apple Wallet link\">${APPLE_SVG}</button>\n             <button class=\"btn\" onclick=\"showGoogleLink('${p.serial}')\" title=\"Save to Google Wallet link\">G</button>\n             <button class=\"btn\" onclick=\"toggleLog('${p.serial}')\" title=\"Message history\">🕒</button>\n             <button class=\"btn\" onclick=\"archivePass('${p.serial}')\">🗄 Archive</button>`}\n        </div>\n      </div>\n      <div class=\"logbox\" id=\"log-${p.serial}\" style=\"display:none\"></div>`;\n}\n\n/* ── message log timeline ── */\nasync function toggleLog(serial) {\n  const box = document.getElementById('log-'+serial);\n  if (box.style.display !== 'none') { box.style.display = 'none'; return; }\n  box.style.display = 'block';\n  box.innerHTML = '<div class=\"logline soft\">Loading history…</div>';\n  try {\n    const data = await api('/v1/passes/'+serial+'/log');\n    const parts = [];\n    for (const s of (data.scheduled||[]).filter(x=>!x.sent_at)) {\n      parts.push(`<div class=\"logline pending\">🕐 <b>scheduled</b> for ${new Date(s.send_at*1000).toLocaleString()} — “${esc(s.message)}”</div>`);\n    }\n    for (const e of data.events || []) {\n      const icon = {created:'✨', updated:'✎', notified:'🔔', scheduled_sent:'🕐→🔔'}[e.kind] || '•';\n      const detail = [e.apple, e.google].filter(Boolean).join(' · ');\n      parts.push(`<div class=\"logline\">${icon} <b>${e.kind.replace('_',' ')}</b> ${rel(e.at)}${e.message ? ' — “'+esc(e.message)+'”' : ''}${detail ? ' <span class=\"soft\">('+esc(detail)+')</span>' : ''}</div>`);\n    }\n    box.innerHTML = parts.length ? parts.join('') : '<div class=\"logline soft\">No history yet.</div>';\n  } catch(e){ box.innerHTML = '<div class=\"logline soft\">Failed: '+esc(e.message)+'</div>'; }\n}\nasync function loadPasses() {\n  const list = document.getElementById('list');\n  try {\n    const data = await api('/v1/passes');\n    const all = data.passes || [];\n    const active = all.filter(p => !p.archived_at);\n    const archived = all.filter(p => p.archived_at);\n    document.getElementById('countSub').innerHTML =\n      active.length + ' card' + (active.length===1?'':'s') + ' · ' +\n      active.filter(p=>p.registrations>0).length + ' installed on a device' +\n      (archived.length ? ` · <a href=\"#\" onclick=\"showArchived=!showArchived;loadPasses();return false\" style=\"color:var(--crimson)\">${showArchived?'hide':'show'} ${archived.length} archived</a>` : '');\n    const visible = showArchived ? [...active, ...archived] : active;\n    if (!visible.length) { list.innerHTML = '<div class=\"empty\">No cards yet.<br>Mint one with “＋ New test card”.</div>'; return; }\n    list.innerHTML = visible.map(passRow).join('');\n  } catch (e) {\n    list.innerHTML = '<div class=\"empty\">Could not load — ' + e.message + '</div>';\n  }\n}\n\n/* ── notify ── */\nfunction showNotify(serial) {\n  currentSerial = serial;\n  document.getElementById('notifySerial').textContent = serial;\n  document.getElementById('notifyMsg').value = '';\n  show('notifyOverlay');\n  document.getElementById('notifyMsg').focus();\n}\nasync function sendNotify() {\n  const msg = document.getElementById('notifyMsg').value.trim();\n  if (!msg) return;\n  const btn = document.getElementById('notifySend'); btn.disabled = true;\n  try {\n    const r = await api('/v1/passes/'+currentSerial, { method:'PATCH', body: JSON.stringify({ changeMessage: msg }) });\n    hide('notifyOverlay');\n    const gNote = r.google && r.google !== 'not_configured' && r.google !== 'no_object' ? ' · Google: '+r.google : '';\n    toast((r.pushed ? '🔔 Apple: '+r.pushed+' device'+(r.pushed===1?'':'s') : 'No Apple devices')+gNote);\n    loadPasses();\n  } catch(e){ toast('Failed: '+e.message); }\n  btn.disabled = false;\n}\n\n/* ── edit ── */\nconst FIELD_IDS = ['guest','event','due','acts','promise','movement','photoUrl'];\nasync function showEdit(serial) {\n  currentSerial = serial;\n  document.getElementById('editSerial').textContent = serial;\n  show('editOverlay');\n  try {\n    const data = await api('/v1/passes/'+serial);\n    for (const k of FIELD_IDS) document.getElementById('f_'+k).value = (data.fields||{})[k] ?? '';\n  } catch(e){ toast('Failed to load: '+e.message); }\n}\nasync function saveFields() {\n  const fields = {};\n  for (const k of FIELD_IDS) fields[k] = document.getElementById('f_'+k).value;\n  try {\n    await api('/v1/passes/'+currentSerial, { method:'PATCH', body: JSON.stringify({ fields }) });\n    hide('editOverlay'); toast('Saved & pushed ✓'); loadPasses();\n  } catch(e){ toast('Failed: '+e.message); }\n}\n\n/* ── brands ── */\nlet brandKey = null;\nasync function showBrands() {\n  document.getElementById('brandKeyBox').style.display = 'none';\n  document.getElementById('b_id').value = ''; document.getElementById('b_name').value = '';\n  show('brandsOverlay');\n  const list = document.getElementById('brandsList');\n  list.innerHTML = '<div class=\"logline soft\">Loading…</div>';\n  try {\n    const data = await api('/v1/brands');\n    list.innerHTML = (data.brands||[]).map(b =>\n      `<div class=\"logline\">🏷 <b>${esc(b.name)}</b> <span class=\"soft\">(${esc(b.id)} · created ${rel(b.created_at)})</span></div>`\n    ).join('') || '<div class=\"logline soft\">No brands yet.</div>';\n  } catch(e){ list.innerHTML = '<div class=\"logline soft\">Failed: '+esc(e.message)+'</div>'; }\n}\nasync function createBrand() {\n  const id = document.getElementById('b_id').value.trim().toLowerCase();\n  const name = document.getElementById('b_name').value.trim();\n  if (!id || !name) { toast('Need both an ID and a name'); return; }\n  try {\n    const r = await api('/v1/brands', { method:'POST', body: JSON.stringify({ id, name }) });\n    if (!r.apiKey) throw new Error(r.message || r.error || 'failed');\n    brandKey = r.apiKey;\n    document.getElementById('brandKeyVal').textContent = r.apiKey;\n    document.getElementById('brandKeyBox').style.display = 'block';\n    showBrandsListOnly();\n  } catch(e){ toast('Failed: '+e.message); }\n}\nasync function showBrandsListOnly(){\n  try { const data = await api('/v1/brands');\n    document.getElementById('brandsList').innerHTML = (data.brands||[]).map(b =>\n      `<div class=\"logline\">🏷 <b>${esc(b.name)}</b> <span class=\"soft\">(${esc(b.id)})</span></div>`).join('');\n  } catch {}\n}\nfunction copyBrandKey(){ if(brandKey){ navigator.clipboard.writeText(brandKey); toast('Key copied — store it safely'); } }\n\n/* ── apple re-add link ── */\nlet appleLink = null;\nasync function showAppleLink(serial) {\n  document.getElementById('appleSerial').textContent = serial;\n  document.getElementById('appleBody').innerHTML = '<div class=\"note\" style=\"text-align:center\">Preparing the link…</div>';\n  document.getElementById('appleCopy').style.display = 'none';\n  show('appleOverlay');\n  try {\n    const data = await api('/v1/passes/'+serial+'/apple-link');\n    if (!data.url) throw new Error(data.error || 'no link returned');\n    appleLink = data.url;\n    const qr = qrcode(0, 'M'); qr.addData(data.url); qr.make();\n    document.getElementById('appleBody').innerHTML =\n      '<div style=\"display:grid;place-items:center;padding:6px 0\">'+qr.createImgTag(4,10)+'</div>' +\n      '<div class=\"note\" style=\"text-align:center\"><a href=\"'+data.url+'\" target=\"_blank\" rel=\"noopener\">Open .pkpass link ↗</a></div>';\n    document.getElementById('appleCopy').style.display = '';\n  } catch(e){\n    document.getElementById('appleBody').innerHTML = '<div class=\"note\" style=\"color:var(--crimson)\">Failed: '+esc(e.message)+'</div>';\n  }\n}\nfunction copyAppleLink(){ if(appleLink){ navigator.clipboard.writeText(appleLink); toast('Link copied'); } }\n\n/* ── google save link ── */\nlet googleLink = null;\nasync function showGoogleLink(serial) {\n  currentSerial = serial;\n  document.getElementById('googleSerial').textContent = serial;\n  document.getElementById('googleBody').innerHTML = '<div class=\"note\" style=\"text-align:center\">Creating the Google pass…</div>';\n  document.getElementById('googleCopy').style.display = 'none';\n  show('googleOverlay');\n  try {\n    const data = await api('/v1/passes/'+serial+'/google-link');\n    if (!data.saveUrl) throw new Error(data.error || 'no link returned');\n    googleLink = data.saveUrl;\n    const qr = qrcode(0, 'M'); qr.addData(data.saveUrl); qr.make();\n    document.getElementById('googleBody').innerHTML =\n      '<div id=\"qrBoxG\" style=\"display:grid;place-items:center;padding:6px 0\">'+qr.createImgTag(3,8)+'</div>' +\n      '<div class=\"note\" style=\"text-align:center\"><a href=\"'+data.saveUrl+'\" target=\"_blank\" rel=\"noopener\">Open save link ↗</a></div>';\n    document.getElementById('googleCopy').style.display = '';\n  } catch(e){\n    document.getElementById('googleBody').innerHTML = '<div class=\"note\" style=\"color:var(--crimson)\">Failed: '+esc(e.message)+'</div>';\n  }\n}\nfunction copyGoogleLink(){ if(googleLink){ navigator.clipboard.writeText(googleLink); toast('Link copied'); } }\n\n/* ── new card QR ── */\nfunction showQr() {\n  const url = (DEMO ? 'https://digital-pass.small-bread-a578.workers.dev' : location.origin) + '/v1/test-pass';\n  const qr = qrcode(0, 'M'); qr.addData(url); qr.make();\n  document.getElementById('qrBox').innerHTML = qr.createImgTag(5, 10);\n  document.getElementById('qrUrlNote').textContent = url;\n  show('qrOverlay');\n}\n\n/* ── archive (data is never destroyed) ── */\nasync function archivePass(serial) {\n  try {\n    await api('/v1/passes/'+serial+'?action=archive', { method:'POST' });\n    toast('🗄 Archived — find it under \"show archived\"');\n    loadPasses();\n  } catch(e){ toast('Failed: '+e.message); }\n}\nasync function unarchivePass(serial) {\n  try {\n    await api('/v1/passes/'+serial+'?action=unarchive', { method:'POST' });\n    toast('Restored to active cards');\n    loadPasses();\n  } catch(e){ toast('Failed: '+e.message); }\n}\n\n/* ── utils ── */\nfunction esc(s){ return s ? String(s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])) : s; }\nfunction show(id){ document.getElementById(id).classList.add('show'); }\nfunction hide(id){ document.getElementById(id).classList.remove('show'); }\nfunction toast(t){ const el=document.getElementById('toast'); el.textContent=t; el.classList.add('show'); setTimeout(()=>el.classList.remove('show'),2600); }\n\n/* ── boot ── */\nif (DEMO) {\n  document.getElementById('demoBadge').style.display = '';\n  KEY = 'demo'; enter();\n} else {\n  const saved = localStorage.getItem('psk');\n  if (saved) { KEY = saved; api('/v1/passes').then(enter).catch(()=>localStorage.removeItem('psk')); }\n}\n</script>\n</body>\n</html>\n";
export const BUILDER_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Pass Studio — Builder</title>\n<style>\n  :root{\n    --bg:#f6f6f4; --panel:#fff; --ink:#1a1a1a; --ink-soft:#6b6b6b; --line:#e7e5e0;\n    --crimson:#a4133c; --crimson-deep:#800f2f; --blush:#fff0f3; --chip:#f1efe9; --good:#1a7f4e;\n  }\n  *{box-sizing:border-box;margin:0;padding:0;}\n  html,body{height:100%;}\n  body{font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Inter,sans-serif;background:var(--bg);color:var(--ink);overflow:hidden;}\n  .app{display:flex;flex-direction:column;height:100vh;}\n\n  .topbar{display:flex;align-items:center;gap:14px;padding:10px 18px;background:var(--panel);border-bottom:1px solid var(--line);}\n  .brandmark{display:flex;align-items:center;gap:9px;font-weight:700;font-size:15px;}\n  .brandmark .dot{width:26px;height:26px;border-radius:8px;background:linear-gradient(160deg,#800f2f,#c9184a);display:grid;place-items:center;color:#fff;font-size:13px;}\n  .crumb{color:var(--ink-soft);font-size:13px;}\n  select#brandSel{border:1px solid var(--line);border-radius:9px;padding:7px 10px;font-size:13px;font-family:inherit;background:#fff;}\n  .topbar .right{margin-left:auto;display:flex;gap:10px;}\n  .btn{border:1px solid var(--line);background:#fff;padding:8px 14px;border-radius:9px;font-size:13px;font-weight:600;cursor:pointer;font-family:inherit;color:var(--ink);}\n  .btn:hover{border-color:#cfcbc2;}\n  .btn.primary{background:var(--crimson);border-color:var(--crimson);color:#fff;}\n  .btn.primary:disabled{opacity:.5;cursor:default;}\n\n  .main{display:flex;flex:1;min-height:0;}\n\n  /* ── companion / editor panel (LEFT 1/3) ── */\n  .companion{flex:1;min-width:330px;max-width:440px;background:var(--panel);border-right:1px solid var(--line);display:flex;flex-direction:column;}\n  .comp-head{padding:13px 18px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:10px;}\n  .comp-avatar{width:32px;height:32px;border-radius:50%;background:conic-gradient(from 210deg,#a4133c,#ff758f,#ffd166,#a4133c);display:grid;place-items:center;color:#fff;font-size:14px;}\n  .comp-head .t{font-weight:700;font-size:14px;}\n  .comp-head .s{font-size:11.5px;color:var(--good);}\n  .comp-body{flex:1;overflow-y:auto;padding:16px;}\n  .guide{background:#faf8f3;border:1px solid var(--line);border-radius:4px 14px 14px 14px;padding:11px 13px;font-size:13px;line-height:1.5;margin-bottom:14px;}\n  .guide b{color:var(--crimson);}\n  .ed{border:1px solid var(--line);border-radius:14px;padding:14px;margin-bottom:14px;background:#fff;}\n  .ed h3{font-size:11px;font-weight:800;letter-spacing:.8px;color:var(--crimson);margin-bottom:10px;}\n  .ed label{display:block;font-size:10.5px;font-weight:700;letter-spacing:.5px;color:var(--ink-soft);margin:9px 0 4px;}\n  .ed input[type=text],.ed select,.ed textarea{width:100%;border:1px solid var(--line);border-radius:8px;padding:8px 10px;font-size:13px;font-family:inherit;}\n  .ed .rowline{display:flex;gap:10px;}\n  .ed .rowline>div{flex:1;}\n  .ed .mini-note{font-size:11.5px;color:var(--ink-soft);margin-top:8px;line-height:1.45;}\n  .ed .danger{color:var(--crimson);border-color:#f0d4dc;margin-top:10px;}\n  .colorrow{display:flex;align-items:center;gap:10px;margin-top:6px;}\n  .colorrow input[type=color]{width:38px;height:30px;border:1px solid var(--line);border-radius:8px;padding:2px;background:#fff;}\n  .colorrow span{font-size:12px;color:var(--ink-soft);}\n  .addbtns{display:flex;flex-wrap:wrap;gap:8px;}\n  .chip{border:1px solid var(--line);background:#fff;border-radius:99px;padding:6px 12px;font-size:12px;cursor:pointer;font-family:inherit;font-weight:600;}\n  .chip:hover{border-color:var(--crimson);color:var(--crimson);}\n\n  /* ── canvas (RIGHT 2/3) ── */\n  .viewer{flex:2;position:relative;display:flex;align-items:center;justify-content:center;overflow:auto;padding:30px;\n    background:radial-gradient(ellipse at 30% 20%, #efece6 0%, transparent 55%),var(--bg);}\n  .viewer-hint{position:absolute;top:14px;left:50%;transform:translateX(-50%);font-size:12px;color:var(--ink-soft);background:#fffdf8;border:1px solid var(--line);padding:6px 14px;border-radius:99px;white-space:nowrap;}\n  .viewer-hint b{color:var(--crimson);}\n  .viewer-tools{position:absolute;bottom:16px;left:50%;transform:translateX(-50%);display:flex;gap:8px;}\n\n  .pass{width:340px;border-radius:18px;color:#fff;box-shadow:0 24px 60px -18px rgba(0,0,0,.4);overflow:hidden;}\n  .pass .inner{padding:0 0 6px;}\n  .phead{display:flex;align-items:flex-start;justify-content:space-between;padding:13px 15px 10px;gap:10px;}\n  .plogo{display:flex;align-items:center;gap:8px;min-width:0;}\n  .plogo .heart{width:28px;height:28px;border-radius:8px;background:rgba(255,255,255,.18);display:grid;place-items:center;font-size:14px;flex-shrink:0;}\n  .plogo span{font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n  .hfields{display:flex;gap:12px;flex-shrink:0;}\n  .pf{cursor:pointer;position:relative;border-radius:6px;padding:2px 4px;transition:box-shadow .12s;}\n  .pf:hover{box-shadow:inset 0 0 0 2px rgba(255,255,255,.5);}\n  .pf.sel{box-shadow:inset 0 0 0 2px #ffd166;}\n  .pf .lbl{font-size:8.5px;letter-spacing:1.1px;opacity:.75;font-weight:700;}\n  .pf .val{font-weight:700;}\n  .hfields .val{font-size:13px;text-align:right;}\n  .pbody{padding:6px 15px 12px;}\n  .primary-f .val{font-size:17.5px;line-height:1.25;}\n  .frow{display:flex;justify-content:space-between;gap:10px;margin-top:11px;flex-wrap:wrap;}\n  .frow .pf .val{font-size:13.5px;}\n  .qr-zone{display:flex;justify-content:center;padding:8px 0 12px;cursor:pointer;border-radius:8px;}\n  .qr-zone:hover{box-shadow:inset 0 0 0 2px rgba(255,255,255,.5);}\n  .qr-zone.sel{box-shadow:inset 0 0 0 2px #ffd166;}\n  .qr-card{background:#fff;border-radius:12px;padding:8px;display:flex;flex-direction:column;align-items:center;gap:4px;}\n  .qrbox{width:74px;height:74px;background:repeating-conic-gradient(#111 0% 25%, #fff 0% 50%) 0 0/14px 14px;border-radius:4px;}\n  .qr-cap{font-size:8px;color:#777;font-weight:600;max-width:120px;text-align:center;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}\n  .backface{padding:4px 15px 12px;}\n  .bfield{padding:10px 4px;border-top:1px solid rgba(255,255,255,.16);}\n  .empty-sec{font-size:10px;opacity:.5;padding:6px 4px;border:1px dashed rgba(255,255,255,.35);border-radius:8px;text-align:center;margin-top:10px;cursor:pointer;}\n\n  .comp-chat{border-top:1px solid var(--line);flex-shrink:0;display:flex;flex-direction:column;max-height:38%;}\n  .chat-stream{overflow-y:auto;padding:10px 14px;display:flex;flex-direction:column;gap:8px;}\n  .msg{max-width:92%;font-size:12.5px;line-height:1.45;padding:8px 11px;border-radius:12px;}\n  .msg.ai{align-self:flex-start;background:#faf8f3;border:1px solid var(--line);border-radius:4px 12px 12px 12px;}\n  .msg.ai b{color:var(--crimson);}\n  .msg.user{align-self:flex-end;background:var(--ink);color:#fff;border-radius:12px 4px 12px 12px;}\n  .chat-box{display:flex;gap:8px;padding:10px 14px 14px;}\n  .chat-box input{flex:1;border:1px solid var(--line);border-radius:10px;padding:9px 12px;font-size:13px;font-family:inherit;}\n  .chat-box .send{border:0;background:var(--crimson);color:#fff;width:34px;height:34px;border-radius:9px;cursor:pointer;font-size:14px;}\n  .swatches{display:flex;gap:8px;margin-top:10px;}\n  .sw{width:30px;height:30px;border-radius:9px;cursor:pointer;border:2px solid transparent;transition:transform .12s;}\n  .sw:hover{transform:scale(1.12);}\n  .sw.crimson{background:linear-gradient(140deg,#800f2f,#c9184a);}\n  .sw.sunset{background:linear-gradient(140deg,#e85d04,#ffba08);}\n  .sw.ocean{background:linear-gradient(140deg,#023e8a,#00b4d8);}\n  .sw.forest{background:linear-gradient(140deg,#1b4332,#52b788);}\n  .sw.night{background:linear-gradient(140deg,#10002b,#5a189a);}\n  .toast{position:fixed;bottom:22px;right:22px;background:var(--ink);color:#fff;font-size:13px;padding:10px 18px;border-radius:99px;opacity:0;transition:all .25s;pointer-events:none;z-index:99;}\n  .toast.show{opacity:1;}\n  .gate{max-width:420px;margin:90px auto;background:#fff;border:1px solid var(--line);border-radius:16px;padding:28px;text-align:center;}\n  .gate input{width:100%;border:1px solid var(--line);border-radius:10px;padding:11px;font-size:14px;text-align:center;margin:14px 0 10px;font-family:inherit;}\n</style>\n</head>\n<body>\n<div class=\"app\" id=\"app\" style=\"display:none\">\n  <div class=\"topbar\">\n    <div class=\"brandmark\"><div class=\"dot\">🎨</div> Pass Studio Builder</div>\n    <select id=\"brandSel\" onchange=\"loadBrand(this.value)\"></select>\n    <span class=\"crumb\" id=\"dirtyNote\"></span>\n    <div class=\"right\">\n      <button class=\"btn\" onclick=\"location.href='/admin'\">← Cards</button>\n      <button class=\"btn\" id=\"flipBtn\" onclick=\"flipped=!flipped;renderCard()\">↺ Flip card</button>\n      <button class=\"btn primary\" id=\"publishBtn\" onclick=\"publish()\" disabled>Publish</button>\n    </div>\n  </div>\n\n  <div class=\"main\">\n    <div class=\"companion\">\n      <div class=\"comp-head\">\n        <div class=\"comp-avatar\">✦</div>\n        <div><div class=\"t\">Companion</div><div class=\"s\">● Editing the template</div></div>\n      </div>\n      <div class=\"comp-body\" id=\"panel\"></div>\n      <div class=\"comp-chat\">\n        <div class=\"chat-stream\" id=\"chatStream\"></div>\n        <div class=\"chat-box\">\n          <input id=\"chatInput\" type=\"text\" placeholder=\"“make it ocean blue” · “add field points” · “flip”\" onkeydown=\"if(event.key==='Enter')sendChat()\">\n          <button class=\"send\" onclick=\"sendChat()\">➤</button>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"viewer\">\n      <div class=\"viewer-hint\">Click any part of the card — <b>you're editing the real template</b></div>\n      <div class=\"pass\" id=\"pass\"></div>\n      <div class=\"viewer-tools\"></div>\n    </div>\n  </div>\n</div>\n\n<div class=\"gate\" id=\"gate\" style=\"display:none\">\n  <h2 style=\"font-size:17px\">Builder</h2>\n  <p style=\"font-size:13px;color:var(--ink-soft);margin-top:6px\">Enter your admin key</p>\n  <input type=\"password\" id=\"keyInput\" onkeydown=\"if(event.key==='Enter')connect()\">\n  <button class=\"btn primary\" style=\"width:100%\" onclick=\"connect()\">Open builder</button>\n</div>\n\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\nlet KEY=null, brandId=null, tpl=null, dirty=false, flipped=false;\nlet sel=null; // {type:'field',section,idx} | {type:'logo'} | {type:'colors'} | {type:'barcode'}\n\nconst SECTIONS=[['header','HEADER (top right)'],['primary','PRIMARY (headline)'],['secondary','SECONDARY'],['auxiliary','AUXILIARY'],['back','BACK OF CARD']];\n\nfunction toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600);}\nfunction esc(s){return s?String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])):'';}\nasync function api(path,opts={}){\n  const res=await fetch(path,{...opts,headers:{'X-Admin-Key':KEY,'Content-Type':'application/json',...(opts.headers||{})}});\n  if(res.status===401)throw new Error('unauthorized');\n  return res.json();\n}\n\n/* ── auth + boot ── */\nasync function connect(){\n  KEY=document.getElementById('keyInput').value.trim();\n  try{await api('/v1/brands');localStorage.setItem('psk',KEY);boot();}\n  catch{toast('Key rejected');}\n}\nasync function boot(){\n  document.getElementById('gate').style.display='none';\n  document.getElementById('app').style.display='flex';\n  const data=await api('/v1/brands');\n  const s=document.getElementById('brandSel');\n  s.innerHTML=(data.brands||[]).map(b=>`<option value=\"${esc(b.id)}\">${esc(b.name)} (${esc(b.id)})</option>`).join('');\n  if(data.brands&&data.brands.length)loadBrand(data.brands[0].id);\n  else document.getElementById('panel').innerHTML='<div class=\"guide\">No brands yet — create one in <b>Cards → 🏷 Brands</b> first.</div>';\n}\n(function(){\n  const saved=localStorage.getItem('psk');\n  if(saved){KEY=saved;api('/v1/brands').then(()=>boot()).catch(()=>{localStorage.removeItem('psk');document.getElementById('gate').style.display='block';});}\n  else document.getElementById('gate').style.display='block';\n})();\n\n/* ── template load/publish ── */\nasync function loadBrand(id){\n  if(dirty&&!confirm('Discard unpublished changes?'))return;\n  brandId=id;\n  const data=await api('/v1/brands/'+id+'/template');\n  tpl=data.effective; dirty=false; sel=null; flipped=false;\n  updateDirty(); renderCard(); showHome();\n}\nasync function publish(){\n  try{\n    await api('/v1/brands/'+brandId+'/template',{method:'PUT',body:JSON.stringify(tpl)});\n    dirty=false;updateDirty();\n    toast('🚀 Published — every '+brandId+' card re-renders on its next refresh');\n  }catch(e){toast('Publish failed: '+e.message);}\n}\nfunction markDirty(){dirty=true;updateDirty();renderCard();}\nfunction updateDirty(){\n  document.getElementById('publishBtn').disabled=!dirty;\n  document.getElementById('dirtyNote').textContent=dirty?'● unpublished changes':'';\n}\n\n/* ── card canvas ── */\nfunction fval(f){return f.value!=null?f.value.replace('{barcode}','(link)').replace('{photoUrl}','(photo)'):(tpl.defaults[f.key]??'—');}\nfunction fieldHtml(section,i,f,extra){\n  const s=sel&&sel.type==='field'&&sel.section===section&&sel.idx===i?' sel':'';\n  return `<div class=\"pf${s} ${extra||''}\" onclick=\"event.stopPropagation();pick('field','${section}',${i})\">\n    <div class=\"lbl\">${esc(f.label||f.key)}</div><div class=\"val\">${esc(fval(f))}</div></div>`;\n}\nfunction renderCard(){\n  const p=document.getElementById('pass');\n  p.style.background=`linear-gradient(160deg, ${shade(tpl.colors.bg,-18)} 0%, ${tpl.colors.bg} 55%, ${shade(tpl.colors.bg,22)} 100%)`;\n  p.style.color=tpl.colors.fg;\n  const F=tpl.fields;\n  let html=`<div class=\"inner\">\n    <div class=\"phead\">\n      <div class=\"plogo pf${sel&&sel.type==='logo'?' sel':''}\" onclick=\"event.stopPropagation();pick('logo')\">\n        <div class=\"heart\">💗</div><span>${esc(tpl.logoText||tpl.orgName)}</span>\n      </div>\n      <div class=\"hfields\">${(F.header||[]).map((f,i)=>fieldHtml('header',i,f)).join('')||sectionAdd('header')}</div>\n    </div>`;\n  if(!flipped){\n    html+=`<div class=\"pbody\">\n      ${(F.primary||[]).map((f,i)=>fieldHtml('primary',i,f,'primary-f')).join('')||sectionAdd('primary')}\n      <div class=\"frow\">${(F.secondary||[]).map((f,i)=>fieldHtml('secondary',i,f)).join('')||sectionAdd('secondary')}</div>\n      <div class=\"frow\">${(F.auxiliary||[]).map((f,i)=>fieldHtml('auxiliary',i,f)).join('')||sectionAdd('auxiliary')}</div>\n    </div>\n    <div class=\"qr-zone${sel&&sel.type==='barcode'?' sel':''}\" onclick=\"event.stopPropagation();pick('barcode')\">\n      <div class=\"qr-card\"><div class=\"qrbox\"></div><div class=\"qr-cap\">${esc(barcodePreview())}</div></div>\n    </div>`;\n  } else {\n    html+=`<div class=\"backface\">\n      <div style=\"font-size:10px;font-weight:800;letter-spacing:1px;opacity:.7;padding:4px\">BACK OF CARD</div>\n      ${(F.back||[]).map((f,i)=>`<div class=\"bfield\">${fieldHtml('back',i,f)}</div>`).join('')||sectionAdd('back')}\n    </div>`;\n  }\n  html+='</div>';\n  p.innerHTML=html;\n  p.onclick=()=>pick('colors');\n}\nfunction sectionAdd(section){return `<div class=\"empty-sec\" onclick=\"event.stopPropagation();addField('${section}')\">+ add ${section} field</div>`;}\nfunction barcodePreview(){\n  const b=tpl.barcode||{};\n  if(b.source==='fixed')return b.fixed||'(set a link)';\n  if(b.source==='photoUrl')return \"each card's photo\";\n  return \"each card's own link\";\n}\nfunction shade(rgb,amt){\n  const m=String(rgb).match(/(\\d+)\\s*,\\s*(\\d+)\\s*,\\s*(\\d+)/);if(!m)return rgb;\n  const f=n=>Math.max(0,Math.min(255,Number(n)+amt));\n  return `rgb(${f(m[1])}, ${f(m[2])}, ${f(m[3])})`;\n}\n\n/* ── selection → panel ── */\nfunction pick(type,section,idx){sel={type,section,idx};renderCard();renderPanel();}\nfunction showHome(){sel=null;renderPanel();}\nfunction renderPanel(){\n  const P=document.getElementById('panel');\n  if(!tpl){P.innerHTML='';return;}\n  if(!sel){\n    P.innerHTML=`<div class=\"guide\">This is <b>${esc(tpl.orgName)}</b>'s card template. Click anything on the card to edit it — fields, colors, the logo, the QR. When it's right, hit <b>Publish</b>: every existing ${esc(brandId)} card restyles itself automatically.</div>\n    <div class=\"ed\"><h3>QUICK ACTIONS</h3><div class=\"addbtns\">\n      <button class=\"chip\" onclick=\"pick('logo')\">✎ Name & logo</button>\n      <button class=\"chip\" onclick=\"pick('colors')\">🎨 Colors</button>\n      <button class=\"chip\" onclick=\"pick('barcode')\">⛶ QR / link</button>\n      ${SECTIONS.map(([s])=>`<button class=\"chip\" onclick=\"addField('${s}')\">＋ ${s} field</button>`).join('')}\n    </div></div>`;\n    return;\n  }\n  if(sel.type==='logo'){\n    P.innerHTML=`<div class=\"guide\">The card's identity — shown top-left and as the notification title.</div>\n    <div class=\"ed\"><h3>NAME & LOGO</h3>\n      <label>ORGANIZATION NAME</label><input type=\"text\" value=\"${esc(tpl.orgName)}\" oninput=\"tpl.orgName=this.value;markDirty()\">\n      <label>LOGO TEXT (top-left)</label><input type=\"text\" value=\"${esc(tpl.logoText||'')}\" oninput=\"tpl.logoText=this.value;markDirty()\">\n      <label>CARD DESCRIPTION</label><input type=\"text\" value=\"${esc(tpl.description||'')}\" oninput=\"tpl.description=this.value;markDirty()\">\n    </div>`;\n    return;\n  }\n  if(sel.type==='colors'){\n    P.innerHTML=`<div class=\"guide\">Card colors. Try a palette, or fine-tune each color.</div>\n    <div class=\"ed\"><h3>PALETTES</h3>\n      <div class=\"swatches\">\n        <div class=\"sw crimson\" title=\"Crimson\" onclick=\"setPalette('crimson')\"></div>\n        <div class=\"sw sunset\" title=\"Sunset\" onclick=\"setPalette('sunset')\"></div>\n        <div class=\"sw ocean\" title=\"Ocean\" onclick=\"setPalette('ocean')\"></div>\n        <div class=\"sw forest\" title=\"Forest\" onclick=\"setPalette('forest')\"></div>\n        <div class=\"sw night\" title=\"Night\" onclick=\"setPalette('night')\"></div>\n      </div>\n    </div>\n    <div class=\"ed\"><h3>FINE-TUNE</h3>\n      ${colorEd('Background','bg')}${colorEd('Text','fg')}${colorEd('Labels','label')}\n    </div>`;\n    return;\n  }\n  if(sel.type==='barcode'){\n    const b=tpl.barcode||(tpl.barcode={source:'barcode'});\n    P.innerHTML=`<div class=\"guide\">The QR is for <b>other people's cameras</b> — it opens a link. Choose where it points.</div>\n    <div class=\"ed\"><h3>QR / LINK</h3>\n      <label>POINTS TO</label>\n      <select onchange=\"tpl.barcode.source=this.value;markDirty();renderPanel()\">\n        <option value=\"barcode\"${b.source==='barcode'?' selected':''}>Each card's own link (set at creation)</option>\n        <option value=\"photoUrl\"${b.source==='photoUrl'?' selected':''}>Each card's photo</option>\n        <option value=\"fixed\"${b.source==='fixed'?' selected':''}>One fixed link for all cards</option>\n      </select>\n      ${b.source==='fixed'?`<label>FIXED LINK</label><input type=\"text\" value=\"${esc(b.fixed||'')}\" oninput=\"tpl.barcode.fixed=this.value;markDirty()\">`:''}\n      <label>CAPTION UNDER QR</label><input type=\"text\" value=\"${esc(b.altText||'')}\" oninput=\"tpl.barcode.altText=this.value;markDirty()\">\n    </div>`;\n    return;\n  }\n  // field editor\n  const f=tpl.fields[sel.section][sel.idx];\n  P.innerHTML=`<div class=\"guide\">Editing a <b>${sel.section}</b> field. The label is the small caption; the default shows until a card sets its own value via the API (key: <b>${esc(f.key)}</b>).</div>\n  <div class=\"ed\"><h3>FIELD</h3>\n    <div class=\"rowline\">\n      <div><label>LABEL (shown on card)</label><input type=\"text\" value=\"${esc(f.label||'')}\" oninput=\"tpl.fields['${sel.section}'][${sel.idx}].label=this.value;markDirty()\"></div>\n      <div><label>KEY (for the API)</label><input type=\"text\" value=\"${esc(f.key)}\" oninput=\"tpl.fields['${sel.section}'][${sel.idx}].key=this.value.replace(/\\\\W/g,'');markDirty()\"></div>\n    </div>\n    ${f.value!=null\n      ?`<label>FIXED TEXT ({barcode}/{photoUrl} allowed)</label><input type=\"text\" value=\"${esc(f.value)}\" oninput=\"tpl.fields['${sel.section}'][${sel.idx}].value=this.value;markDirty()\">`\n      :`<label>DEFAULT VALUE</label><input type=\"text\" value=\"${esc(tpl.defaults[f.key]??'')}\" oninput=\"tpl.defaults['${esc(f.key)}']=this.value;markDirty()\">`}\n    <label>NOTIFICATION FORMAT (optional — %@ = new value; fires when this field changes)</label>\n    <input type=\"text\" value=\"${esc(f.changeMessage||'')}\" oninput=\"setCM('${sel.section}',${sel.idx},this.value)\" placeholder=\"e.g. Due date: %@\">\n    <div class=\"mini-note\">Tip: keep ONE field with plain <b>%@</b> as your message channel${f.key===tpl.messageField?' — this is it (messageField)':''}.</div>\n    <button class=\"btn danger\" onclick=\"removeField('${sel.section}',${sel.idx})\">🗑 Remove field</button>\n  </div>`;\n}\nfunction setCM(section,idx,value){\n  const f=tpl.fields[section][idx];\n  if(value)f.changeMessage=value;else delete f.changeMessage;\n  markDirty();\n}\nfunction colorEd(name,key){\n  return `<div class=\"colorrow\"><input type=\"color\" value=\"${rgb2hex(tpl.colors[key])}\" oninput=\"tpl.colors['${key}']=hex2rgb(this.value);markDirty()\"><span>${name} · ${esc(tpl.colors[key])}</span></div>`;\n}\nfunction rgb2hex(rgb){const m=String(rgb).match(/(\\d+)\\s*,\\s*(\\d+)\\s*,\\s*(\\d+)/);if(!m)return'#a4133c';return'#'+[m[1],m[2],m[3]].map(n=>Number(n).toString(16).padStart(2,'0')).join('');}\nfunction hex2rgb(hex){const n=parseInt(hex.slice(1),16);return`rgb(${(n>>16)&255}, ${(n>>8)&255}, ${n&255})`;}\n\n/* ── palettes + companion chat ── */\nconst PALETTES={\n  crimson:{bg:'rgb(164, 19, 60)',fg:'rgb(255, 255, 255)',label:'rgb(255, 214, 224)'},\n  sunset:{bg:'rgb(232, 93, 4)',fg:'rgb(255, 255, 255)',label:'rgb(255, 234, 180)'},\n  ocean:{bg:'rgb(2, 62, 138)',fg:'rgb(255, 255, 255)',label:'rgb(170, 220, 255)'},\n  forest:{bg:'rgb(27, 67, 50)',fg:'rgb(255, 255, 255)',label:'rgb(180, 230, 200)'},\n  night:{bg:'rgb(38, 5, 90)',fg:'rgb(255, 255, 255)',label:'rgb(215, 190, 255)'},\n};\nfunction setPalette(name){\n  if(!PALETTES[name])return;\n  tpl.colors={...PALETTES[name]};markDirty();\n  if(sel&&sel.type==='colors')renderPanel();\n  aiSay(`<b>${name}</b> palette applied — Publish when it feels right.`);\n}\nfunction aiSay(html){const s=document.getElementById('chatStream');const d=document.createElement('div');d.className='msg ai';d.innerHTML=html;s.appendChild(d);s.scrollTop=s.scrollHeight;}\nfunction userSay(t){const s=document.getElementById('chatStream');const d=document.createElement('div');d.className='msg user';d.textContent=t;s.appendChild(d);s.scrollTop=s.scrollHeight;}\nfunction sendChat(){\n  const inp=document.getElementById('chatInput');const v=inp.value.trim();if(!v)return;\n  userSay(v);inp.value='';handleChat(v.toLowerCase(),v);\n}\nfunction handleChat(low,raw){\n  if(!tpl){aiSay('Pick a brand first.');return;}\n  // palettes / colors\n  for(const name of Object.keys(PALETTES)){\n    if(low.includes(name)||({ocean:'blue',forest:'green',night:'purple',sunset:'orange',crimson:'red'}[name]&&low.includes({ocean:'blue',forest:'green',night:'purple',sunset:'orange',crimson:'red'}[name]))){\n      setPalette(name);return;\n    }\n  }\n  if(low.includes('flip')){flipped=!flipped;renderCard();aiSay(flipped?'Flipped — the back of the card.':'Front side.');return;}\n  // add field: \"add field points\" / \"add points to auxiliary\"\n  let m=low.match(/add (?:field )?(\\w+)(?: to (header|primary|secondary|auxiliary|back))?/);\n  if(m&&low.startsWith('add')){\n    const key=m[1].replace(/\\W/g,''),section=m[2]||'auxiliary';\n    tpl.fields[section]=tpl.fields[section]||[];\n    tpl.fields[section].push({key,label:key.toUpperCase()});\n    if(tpl.defaults[key]==null)tpl.defaults[key]='';\n    markDirty();pick('field',section,tpl.fields[section].length-1);\n    aiSay(`Added <b>${key}</b> to ${section} — its editor is open above.`);return;\n  }\n  // rename: \"rename guest to member\"\n  m=raw.match(/rename (\\w+) to (.+)/i);\n  if(m){\n    const from=m[1].toLowerCase(),to=m[2].trim();\n    for(const s of Object.keys(tpl.fields)){\n      for(const f of tpl.fields[s]){\n        if(f.key.toLowerCase()===from||String(f.label||'').toLowerCase()===from){\n          f.label=to.toUpperCase();markDirty();aiSay(`Renamed — the field now shows <b>${to.toUpperCase()}</b>.`);return;\n        }\n      }\n    }\n    aiSay(`Couldn't find a field called “${m[1]}”.`);return;\n  }\n  // org/logo: \"call it X\" / \"name it X\"\n  m=raw.match(/(?:call|name) (?:it|the card) (.+)/i);\n  if(m){tpl.orgName=m[1].trim();tpl.logoText=m[1].trim();markDirty();aiSay(`It's now <b>${esc(m[1].trim())}</b>.`);return;}\n  if(low.includes('publish')){publish();return;}\n  aiSay(`I understand: <b>palette names</b> (crimson/sunset/ocean/forest/night or “blue”, “green”…), <b>add field NAME to SECTION</b>, <b>rename X to Y</b>, <b>call it NAME</b>, <b>flip</b>, <b>publish</b>. For everything else — clicking the card is fastest. (My full AI brain arrives in a later step; today I'm quick-commands.)`);\n}\nsetTimeout(()=>aiSay('Hi David — tell me things like <b>“make it ocean blue”</b>, <b>“add field points”</b>, or click the card directly. <b>Publish</b> makes it real for every card.'),600);\n\n/* ── field add/remove/changeMessage ── */\nfunction addField(section){\n  const key=prompt('New field key (letters/numbers, e.g. points):');\n  if(!key)return;\n  const clean=key.replace(/\\W/g,'');\n  tpl.fields[section]=tpl.fields[section]||[];\n  tpl.fields[section].push({key:clean,label:clean.toUpperCase()});\n  if(tpl.defaults[clean]==null)tpl.defaults[clean]='';\n  markDirty();pick('field',section,tpl.fields[section].length-1);\n}\nfunction removeField(section,idx){\n  tpl.fields[section].splice(idx,1);\n  sel=null;markDirty();renderPanel();\n}\n</script>\n</body>\n</html>\n";
